def sub_line(t, prefix, new):
    ls = t.split('\n'); hits = [i for i, l in enumerate(ls) if l.startswith(prefix)]; assert len(hits) == 1, (prefix, hits); ls[hits[0]] = new; return '\n'.join(ls)
